 this.shadowRoot.innerHTML='<style>'+css+clarityCss+'</style><section class="lesson"><nav></nav><header class="chapter-head"><div class="chapter-title"><p class="eyebrow"></p><h4></h4></div><div class="header-actions"><div class="progress"><span class="chapter-count"></span><span class="timecode" aria-hidden="true"></span></div><button type="button" class="expand"></button></div></header><div class="visual"></div><div class="shot-progress" aria-hidden="true"><span></span></div><div class="narration" aria-live="polite"><span class="step-number"></span><div class="narration-body"></div></div><div class="scrubber"><label for="lesson-step"></label><input id="lesson-step" type="range" min="0" step="1"><output></output></div><footer class="controls"></footer><aside class="takeaway"></aside></section>';
 const $=x=>this.shadowRoot.querySelector(x),en=this.data.lang==='en',word=(zh,enText)=>en?enText:zh;
 $('.lesson').dataset.mode=this.data.mode||'advanced';$('nav').hidden=this.data.chapters.length===1;$('nav').setAttribute('aria-label',word('原理动画章节','Principle lesson chapters'));$('.eyebrow').textContent=word('先理解概念，再学习计算','UNDERSTAND FIRST · CALCULATE NEXT');
 this.buttons=this.data.chapters.map((c,i)=>{const b=document.createElement('button');b.type='button';b.textContent=c.title;b.addEventListener('click',()=>{this.running=false;this.jump(this.frames.findIndex(f=>f.chapter===i));},{signal});$('nav').append(b);return b;});
 const action=(label,kind,fn,quiet=false)=>{const b=document.createElement('button');b.type='button';b.innerHTML=lessonIcon(kind)+'<span></span>';b.querySelector('span').textContent=label;if(quiet)b.className='quiet';b.addEventListener('click',fn,{signal});$('.controls').append(b);return b;};
 this.play=action(word('播放本章','Play chapter'),'play',()=>{if(!this.running&&this.elapsed>=this.interval){this.running=true;this.jump(this.index<this.frames.length-1?this.index+1:this.frames.findIndex(f=>f.chapter===this.frames[this.index].chapter));}else{this.running=!this.running;this.last=performance.now();this.paintControls();}});this.play.dataset.primary='';
 this.previous=action(word(this.data.mode==='intro'?'上一幕':'上一段','Previous'),'previous',()=>{this.running=false;this.jump(this.index-1);});
 this.next=action(word(this.data.mode==='intro'?'下一幕':'下一段','Next'),'next',()=>{this.running=false;this.jump(this.index+1);});
